AssistantMessageToolRequest(name='create', tool_call_id='function-call-5a61a4a5-cc54-4911-af1c-a8bfa5f764ec', arguments={'file_text': ':root {
    --primary-color: #2563eb;
    --text-color: #1f2937;
    --bg-color: #f9fafb;
    --card-bg: #ffffff;
    --border-color: #e5e7eb;
    --focus-ring: #bfdbfe;
    --font-family: system-ui, -apple-system, sans-serif;
}

* {
    box-sizing: border-box;
}

body {
    font-family: var(--font-family);
    line-height: 1.5;
    color: var(--text-color);
    background-color: var(--bg-color);
    margin: 0;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

header {
    background-color: var(--card-bg);
    border-bottom: 1px solid var(--border-color);
    padding: 3rem 0;
    text-align: center;
}

header h1 {
    margin: 0;
    font-size: 2.5rem;
    font-weight: 800;
    color: var(--text-color);
}

header p {
    color: #6b7280;
    font-size: 1.125rem;
    margin-top: 0.5rem;
}

main {
    flex: 1;
    padding: 3rem 0;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;
}

.example {
    background-color: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    margin-bottom: 1rem;
    overflow: hidden;
    transition: box-shadow 0.2s;
}

.example:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.example h3 {
    margin: 0;
}

.example button {
    width: 100%;
    text-align: left;
    background: none;
    border: none;
    padding: 1.25rem 1.5rem;
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-color);
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    outline: none;
}

.example button:focus-visible {
    box-shadow: inset 0 0 0 2px var(--primary-color);
    background-color: #f3f4f6;
}

.example button::after {
    content: '';
    width: 0.75rem;
    height: 0.75rem;
    border-right: 2px solid #9ca3af;
    border-bottom: 2px solid #9ca3af;
    transform: rotate(45deg);
    transition: transform 0.2s;
    margin-left: 1rem;
    flex-shrink: 0;
}

.example button[aria-expanded="true"]::after {
    transform: rotate(-135deg);
}

.details {
    padding: 0 1.5rem 1.25rem;
    color: #4b5563;
    font-size: 1rem;
    line-height: 1.6;
}

.details[hidden] {
    display: none;
}

footer {
    padding: 2rem 0;
    border-top: 1px solid var(--border-color);
    text-align: center;
    font-size: 0.875rem;
    color: #6b7280;
}

@media (max-width: 640px) {
    header h1 {
        font-size: 2rem;
    }
}
