+/**
+ * FAQ Component Data
+ */
+const faqData = [
+    {
+        id: 'purring',
+        question: 'Why do cats purr?',
+        answer: 'Cats purr for several reasons. While it often indicates contentment and relaxation, they also purr when they are stressed, in pain, or even to heal themselves. The frequency of a cat\'s purr has been shown to improve bone density and promote healing.'
+    },
+    {
+        id: 'boxes',
+        question: 'Why do cats love boxes so much?',
+        answer: 'Boxes provide cats with a sense of security and safety. In the wild, cats are both predators and prey, so having a confined space where they can observe their surroundings without being seen is instinctual. It also helps them stay warm!'
+    },
+    {
+        id: 'lifespan',
+        question: 'How long do indoor cats typically live?',
+        answer: 'Indoor cats generally live much longer than outdoor cats. The average lifespan for an indoor cat is 12 to 18 years, though many reach their early 20s with good nutrition and veterinary care.'
+    },
+    {
+        id: 'diet',
+        question: 'What is the best diet for a cat?',
+        answer: 'Cats are obligate carnivores, meaning they require animal protein to survive. A balanced diet of high-quality commercial cat food (wet, dry, or a mix) is usually best. Always ensure they have access to fresh water.'
+    },
+    {
+        id: 'night-vision',
+        question: 'Can cats see in total darkness?',
+        answer: 'Not exactly. Cats cannot see in absolute darkness, but they can see in very low light. They only need about one-sixth of the light humans do to see, thanks to a layer of tissue behind their retina called the tapetum lucidum.'
+    }
+];
+
+/**
+ * Disclosure Component (React-style)
+ */
+function Disclosure({ id, question, answer }) {
+    const container = document.createElement('div');
+    container.className = 'example';
+
+    const heading = document.createElement('h3');
+    
+    const button = document.createElement('button');
+    button.type = 'button';
+    button.id = `button-${id}`;
+    button.setAttribute('aria-expanded', 'false');
+    button.setAttribute('aria-controls', `panel-${id}`);
+    button.textContent = question;
+
+    heading.appendChild(button);
+    container.appendChild(heading);
+
+    const panel = document.createElement('div');
+    panel.id = `panel-${id}`;
+    panel.className = 'details';
+    panel.hidden = true;
+    panel.innerHTML = `<p>${answer}</p>`;
+
+    container.appendChild(panel);
+
+    // Event Listener
+    button.addEventListener('click', () => {
+        const isExpanded = button.getAttribute('aria-expanded') === 'true';
+        button.setAttribute('aria-expanded', !isExpanded);
+        panel.hidden = isExpanded;
+    });
+
+    return container;
+}
+
+/**
+ * Main Application
+ */
+function App() {
+    const root = document.getElementById('faq-root');
+    const container = document.createElement('div');
+    container.className = 'container';
+
+    faqData.forEach(item => {
+        const disclosure = Disclosure(item);
+        container.appendChild(disclosure);
+    });
+
+    root.appendChild(container);
+}
+
+// Initialize the app
+document.addEventListener('DOMContentLoaded', App);
+
")

